import java.util.*;class SummaryRanges{TreeMap<Integer,Integer>m=new TreeMap<>();public SummaryRanges(){}public void addNum(int v){Map.Entry<Integer,Integer>lo=m.floorEntry(v),hi=m.ceilingEntry(v);if(lo!=null&&lo.getValue()>=v)return;int l=v,r=v;if(lo!=null&&lo.getValue()+1==v){l=lo.getKey();r=Math.max(r,lo.getValue());m.remove(lo.getKey());}if(hi!=null&&hi.getKey()==v+1){r=hi.getValue();m.remove(hi.getKey());}m.put(l,r);}public int[][] getIntervals(){int[][]o=new int[m.size()][2];int i=0;for(var e:m.entrySet()){o[i][0]=e.getKey();o[i++][1]=e.getValue();}return o;}}
